const input = $input.first().json;
// Token được Webhook kiểm tra bằng Header Auth credential trước khi tới node này.
const body = input.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Dữ liệu chat không hợp lệ');
const question = typeof body.question === 'string' ? body.question.trim() : '';
if (!question || question.length > 2000 || typeof body.capability !== 'string' || !body.capability || typeof body.conversationId !== 'string' || !body.conversationId) throw new Error('Thiếu hoặc sai dữ liệu chat bắt buộc');
const history = Array.isArray(body.history) ? body.history.slice(-10).filter(message => message && ['USER', 'ASSISTANT'].includes(message.role) && typeof message.content === 'string').map(message => ({ role: message.role, content: message.content })) : [];
return [{ json: { question, capability: body.capability, conversationId: body.conversationId, history } }];

const input = $input.first().json;
const error = input.error ?? input;
const details = typeof error === 'string' ? error : [error?.message, error?.description, error?.cause?.message].filter(value => typeof value === 'string').join(' ');
const status = Number(error?.httpCode ?? error?.statusCode ?? error?.status ?? error?.cause?.status);
let code = 'AI_WORKFLOW_FAILED';
let statusCode = 502;
let message = 'Trợ lý AI gặp lỗi khi xử lý. Vui lòng thử lại sau.';
if (status === 503 || /\b503\b|high demand|service unavailable/i.test(details)) {
  code = 'AI_PROVIDER_UNAVAILABLE'; statusCode = 503;
  message = 'Dịch vụ AI đang quá tải hoặc tạm thời không khả dụng. Vui lòng thử lại sau.';
} else if (status === 429 || /\b429\b|resource_exhausted|too many requests/i.test(details)) {
  code = 'AI_PROVIDER_RATE_LIMITED'; statusCode = 429;
  message = 'Dịch vụ AI đang giới hạn lượt xử lý. Vui lòng thử lại sau.';
}
// Không chuyển tiếp câu hỏi, capability, URL API key hoặc lỗi thô.
return [{ json: { code, error: message, statusCode } }];
